  clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
  chart:'<path d="M4 20V10M10 20V4M16 20v-7M22 20v-12"/>',
  user:'<circle cx="12" cy="8" r="4"/><path d="M5 21c0-4 3-6 7-6s7 2 7 6"/>',
  arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',
  chevron:'<path d="m15 18-6-6 6-6"/>',
  plus:'<path d="M12 5v14M5 12h14"/>',
  check:'<path d="m4 12 5 5L20 6"/>',
  flame:'<path d="M12 22c5 0 8-3.4 8-8.1 0-2.9-1.4-5.4-3.2-7.2.1 2.7-1.1 4.1-2.2 4.5C15.1 6.2 12.5 3.4 10 2c.2 3.8-2 5.8-4 8.4C4.6 12.2 4 13.6 4 15c0 4 3.4 7 8 7z"/>',
  play:'<path d="m8 5 11 7-11 7z"/>',
  sound:'<path d="M11 5 6 9H3v6h3l5 4zM15 9a5 5 0 0 1 0 6M18 6a9 9 0 0 1 0 12"/>',
  close:'<path d="M5 5 19 19M19 5 5 19"/>',
  shield:'<path d="m12 2 8 4v5c0 5-3 9-8 11-5-2-8-6-8-11V6z"/><path d="m8 12 3 3 5-6"/>',
  calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 10h18"/>',
  activity:'<path d="M2 12h4l3-7 5 14 3-7h5"/>',
  target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',
  heart:'<path d="M20 5c-2-2-5-2-7 0l-1 1-1-1C9 3 6 3 4 5s-2 5 0 7l8 8 8-8c2-2 2-5 0-7z"/>',
